var i=`0803-milk-tart`;var n=`world-0803`;var a=`ZA`;var s=`southern-africa`;var r=8;var l=227;var o={en:`Milk Tart`,ua:`Молочний тарт`};var g={en:`Milk Tart is a South Africa dish made with all-purpose flour, chicken egg, whole cow milk. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Молочний тарт, страва кухні країни Південно-Африканська Республіка. Основні складники: пшеничне борошно універсальне, куряче яйце, цільне коров'яче молоко. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,230,`g`],[`unsalted-butter`,110,`g`],[`white-granulated-sugar`,30,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Bake in a preheated 180°C oven for about 20 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 20 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:20,i:[]},{en:`Whisk milk, eggs, sugar and flour over gentle heat into a smooth thick custard; pour into the baked tart shell and refrigerate until firm.`,ua:`Збийте молоко, яйця, цукор і борошно та загустіть на малому вогні до гладкого крему; наповніть випечену основу й охолодіть до застигання.`,t:[`roux-making`],m:10,i:[[`whole-cow-milk`,750,`ml`],[`all-purpose-flour`,45,`g`],[`white-granulated-sugar`,135,`g`],[`unsalted-butter`,35,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Chill the filled tart until the custard holds its shape; dust with cinnamon only after cooling.`,ua:`Охолоджуйте наповнений тарт до повного застигання крему; корицю посипайте після охолодження.`,t:[`gelatin-setting`,`rapid-chilling`],m:180,i:[[`vanilla-extract`,5,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-cinnamon`,3,`g`]]}];var h={slug:i,id:n,country:`ZA`,region:s,servings:8,minutes:227,title:o,text:g,steps:u};export{a as country,h as default,n as id,l as minutes,s as region,r as servings,i as slug,u as steps,g as text,o as title};